-- Seed: Threads landing tool pages (EN + AR). Applied once via:
--   npx wrangler d1 execute tvd-admin-dev --local --file d1/seed-tools.sql
-- Supabase: same rows work with jsonb arrays (replace '...' strings with arrays).

insert into tool_pages (slug, badge, lang, target_keyword, title, description, h1, intro, faqs, related_slugs, status) values
('threads-video-downloader-hd', 'HD VIDEO', 'en', 'Threads Video Downloader',
'Threads Video Downloader HD - Save Public Threads Videos in High Quality',
'Paste a public Threads video link and save the available MP4 in the best published quality. Fast, free, no login required, works on mobile and desktop.',
'Threads Video Downloader HD',
'This landing page targets the high-intent query Threads Video Downloader. Paste any public threads.net or threads.com video link above: the resolver detects the available MP4 renditions and shows only qualities that truly exist, with preview, duration and thumbnail. Everything runs in your browser session against public content only — no account, no software, no watermark added.',
'[{"q":"How do I download a Threads video in HD?","a":"Copy the public Threads video link, paste it into the downloader above and press Download. You will get the best published MP4 rendition with a preview before saving."},{"q":"Do I need a Threads account to download videos?","a":"No. Only publicly accessible posts are supported and no login, password or cookies are ever required."},{"q":"Why is only one quality shown for some videos?","a":"We display only qualities the post actually publishes. If Threads published a single rendition, only that one is offered — qualities are never fabricated."},{"q":"Does it work on iPhone and Android?","a":"Yes. The downloader is a mobile-friendly web page: paste the link in your mobile browser and save the MP4 to your device."}]',
'["threads-photo-downloader","threads-carousel-downloader"]',
'live'),
('threads-photo-downloader', 'PHOTO SAVER', 'en', 'Threads Photo Downloader',
'Threads Photo Downloader - Save Public Threads Photos in Full Size',
'Save public Threads photos with preview, resolution and format info. Paste a link, preview each image and download them one by one. No login needed.',
'Threads Photo Downloader',
'This page targets Threads Photo Downloader searches. Paste a public Threads photo post link to preview every detected image with its resolution and format, then download images individually. Only public posts work; private content is never supported and nothing is stored by default.',
'[{"q":"How do I save a photo from Threads?","a":"Paste the public photo post link into the downloader, wait for the preview grid, then press Download under each image you want."},{"q":"What image quality will I get?","a":"The full-size image as published on Threads, shown with its exact resolution before you download."},{"q":"Can I download all photos from a carousel post?","a":"Yes. Carousel posts are detected automatically and every image gets its own preview and download button, plus a Download All option."}]',
'["threads-video-downloader-hd","threads-carousel-downloader"]',
'live'),
('threads-carousel-downloader', 'CAROUSEL', 'en', 'Threads Carousel Downloader',
'Threads Carousel Downloader - Save Every Photo and Video in a Carousel Post',
'Detect every image and video in a public Threads carousel post. Preview each item with type and resolution, download individually or all at once.',
'Threads Carousel Downloader',
'Carousel posts bundle several photos and videos in one Threads post. This landing page is built for the Threads Carousel Downloader query: paste the post link and each item appears with its own preview, media type, resolution and download button. Mixed photo and video carousels are fully supported.',
'[{"q":"How do I download all media from a Threads carousel?","a":"Paste the carousel post link, wait for all items to be detected, then use Download All or save items one by one."},{"q":"Are videos inside carousels supported?","a":"Yes. Each video item shows its duration and resolution with its own download button, exactly like standalone videos."},{"q":"Is there a ZIP download for carousels?","a":"ZIP export is intentionally not generated on the server to avoid buffering large files in memory. Use Download All for sequential individual saves."}]',
'["threads-video-downloader-hd","threads-photo-downloader"]',
'live'),
('تحميل-فيديو-ثريدز', 'تحميل فيديو', 'ar', 'تحميل فيديو ثريدز',
'تحميل فيديو ثريدز - حفظ مقاطع Threads العامة بجودة عالية',
'الصق رابط فيديو عام من ثريدز واحفظ نسخة MP4 المتاحة بأفضل جودة منشورة. سريع ومجاني وبدون تسجيل دخول، يعمل على الجوال وسطح المكتب.',
'تحميل فيديو ثريدز',
'هذه الصفحة مخصصة للبحث عن تحميل فيديو ثريدز. الصق رابط المنشور العام من threads.net أو threads.com وستظهر لك النسخ المتاحة فعليا مع معاينة ومدة وصورة مصغرة. ندعم المحتوى العام فقط ولا نطلب أي حساب أو كلمات مرور ولا نخزن ملفاتك.',
'[{"q":"كيف أحمل فيديو من ثريدز؟","a":"انسخ رابط الفيديو العام والصقه في أداة التحميل بالأعلى ثم اضغط تحميل لتحصل على أفضل نسخة MP4 متاحة مع معاينة قبل الحفظ."},{"q":"هل أحتاج حساب ثريدز للتحميل؟","a":"لا. ندعم المنشورات العامة فقط ولا نطلب تسجيل الدخول أو أي بيانات اعتماد."},{"q":"هل يعمل على الايفون والاندرويد؟","a":"نعم. الأداة صفحة ويب متوافقة مع الجوال: الصق الرابط في متصفح هاتفك واحفظ الفيديو على جهازك."}]',
'["تنزيل-مقاطع-ثريدز"]',
'live'),
('تنزيل-مقاطع-ثريدز', 'تنزيل مقاطع', 'ar', 'تنزيل مقاطع ثريدز',
'تنزيل مقاطع ثريدز - احفظ فيديوهات وصور Threads العامة مجانا',
'نزل مقاطع الفيديو والصور من منشورات ثريدز العامة بجودة عالية. سريع ومجاني وبدون حساب، مع معاينة قبل التحميل.',
'تنزيل مقاطع ثريدز',
'صفحة مخصصة للباحثين عن تنزيل مقاطع ثريدز بالعربية. تدعم الأداة الفيديو والصور ومنشورات الكاروسيل التي تجمع عدة وسائط، مع أزرار تحميل فردية وزر تحميل الكل. المحتوى الخاص غير مدعوم إطلاقا.',
'[{"q":"كيف أنزل مقطعا من ثريدز؟","a":"الصق رابط المنشور العام في الأداة وانتظر اكتشاف الوسائط ثم اختر الجودة أو العنصر وحمله."},{"q":"هل يمكن تحميل صور الكاروسيل؟","a":"نعم. يتم اكتشاف كل صورة وفيديو في منشور الكاروسيل تلقائيا مع معاينة وزر تحميل لكل عنصر."},{"q":"هل الموقع مجاني؟","a":"نعم، الاستخدام مجاني ولا يتطلب تسجيلا أو تثبيت أي برنامج."}]',
'["تحميل-فيديو-ثريدز"]',
'live');
